            </DialogPanel>
            <DialogFooter><Button disabled={pending || !name.trim() || !selectedPrincipalId} type='submit'>{pending ? 'Creating…' : 'Create API key'}</Button></DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

